#ifndef FILESYSTEM_H
#define FILESYSTEM_H

#include <string>
#include <cstdlib>
#include <filesystem>
#include "root_directory.h" // This is a configuration file generated by CMake.

#if defined(__APPLE__)
#include <mach-o/dyld.h>
#endif

// Finds resources/ for a dev build and for a shipped one. The root is the
// first of: LOGL_ROOT_PATH; the source tree baked in at configure time (dev
// builds); the folder holding the executable or one of its parents, or a
// macOS bundle's Contents/Resources (release zips, wherever they unpack).
// SUIKA_SHIPPED=1 skips the source tree, so smoke tests see what players do.
class FileSystem
{
public:
  static std::string getPath(const std::string& path)
  {
    const std::string& root = getRoot();
    return root.empty() ? path : root + "/" + path;
  }

  static const std::string& getRoot()
  {
#ifdef __EMSCRIPTEN__
    static std::string root = "";
#else
    static std::string root = findRoot();
#endif
    return root;
  }

private:
  static bool hasResources(const std::filesystem::path& dir)
  {
    std::error_code ec;
    return std::filesystem::exists(dir / "resources" / "shaders" / "raymarch4d.fs", ec);
  }

  static std::filesystem::path executablePath()
  {
#if defined(_WIN32)
    char* exe = nullptr; // the CRT's copy of the executable path, no <windows.h> needed
    return _get_pgmptr(&exe) == 0 && exe ? std::filesystem::path(exe) : std::filesystem::path();
#elif defined(__APPLE__)
    char buf[4096];
    uint32_t size = sizeof(buf);
    return _NSGetExecutablePath(buf, &size) == 0 ? std::filesystem::path(buf) : std::filesystem::path();
#else
    std::error_code ec;
    return std::filesystem::read_symlink("/proc/self/exe", ec);
#endif
  }

  static std::string findRoot()
  {
    if (const char* env = std::getenv("LOGL_ROOT_PATH")) return env;
    const char* shipped = std::getenv("SUIKA_SHIPPED");
    bool asShipped = shipped && shipped[0] == '1';
    if (!asShipped && logl_root && hasResources(logl_root)) return logl_root;
    std::filesystem::path dir = executablePath().parent_path();
    if (!dir.empty()) {
      if (hasResources(dir / ".." / "Resources")) return (dir / ".." / "Resources").lexically_normal().string();
      for (int up = 0; up < 4 && !dir.empty(); ++up, dir = dir.parent_path())
        if (hasResources(dir)) return dir.string();
    }
    return "."; // the working directory, as a last resort
  }
};

// FILESYSTEM_H
#endif
